// Some portions generated by Codex
package org.eclipse.rdf4j.sail.lmdb.frontier;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;

import java.util.List;

import org.junit.jupiter.api.Test;

/** Explicit producer guarantees survive exact mutation overlays without inventing coverage. */
class FrontierLeafEvidenceGuaranteeTest {

	private static final FrontierLeafProbe PROBE = new FrontierLeafProbe(FrontierLeafProbe.EXPLICIT,
			FrontierLeafProbe.PREDICATE, 0L, 2L, 0L, 0L);

	@Test
	void legacyConstructorsNeverInferExactnessFromTextOrEqualEndpoints() {
		FrontierLeafEstimate sample = new FrontierLeafEstimate(0.0d, 0.0d, 0.0d, 0.5d,
				"frontier-v2-exact", FrontierFallbackReason.NONE);
		assertEquals(FrontierLeafEstimate.Guarantee.ESTIMATE, sample.guarantee());
		assertEquals(FrontierLeafEstimate.Guarantee.UNAVAILABLE,
				FrontierLeafEstimate.unavailable(FrontierFallbackReason.MEMORY_PRESSURE).guarantee());
		assertThrows(IllegalArgumentException.class, () -> new FrontierLeafEstimate(1.0d, 0.0d, 2.0d, 1.0d,
				"not-exact", FrontierFallbackReason.NONE, FrontierLeafEstimate.Guarantee.EXACT));
		assertThrows(IllegalArgumentException.class, () -> new FrontierLeafEstimate(1.0d, Double.NaN, 2.0d, 1.0d,
				"invalid-bounds", FrontierFallbackReason.NONE, FrontierLeafEstimate.Guarantee.CERTIFIED_BOUNDS));
	}

	@Test
	void mutationTailRetainsOnlyTheGuaranteeProvedByItsBase() {
		FrontierMutationTail tail = oneMatchingInsert();
		FrontierLeafEstimate exact = new FrontierLeafEstimate(3.0d, 3.0d, 3.0d, 1.0d,
				"exact-base", FrontierFallbackReason.NONE, FrontierLeafEstimate.Guarantee.EXACT);
		FrontierLeafEstimate adjusted = tail.adjustLeaf(exact, PROBE);
		assertEquals(4.0d, adjusted.pointRows());
		assertEquals(4.0d, adjusted.lowerRows());
		assertEquals(4.0d, adjusted.upperRows());
		assertEquals(FrontierLeafEstimate.Guarantee.EXACT, adjusted.guarantee());

		FrontierLeafEstimate bounds = new FrontierLeafEstimate(3.0d, 1.0d, 5.0d, 0.75d,
				"bounded-base", FrontierFallbackReason.NONE, FrontierLeafEstimate.Guarantee.CERTIFIED_BOUNDS);
		adjusted = tail.adjustLeaf(bounds, PROBE);
		assertEquals(4.0d, adjusted.pointRows());
		assertEquals(2.0d, adjusted.lowerRows());
		assertEquals(6.0d, adjusted.upperRows());
		assertEquals(FrontierLeafEstimate.Guarantee.CERTIFIED_BOUNDS, adjusted.guarantee());

		FrontierLeafEstimate sampledZero = new FrontierLeafEstimate(0.0d, 0.0d, 0.0d, 0.5d,
				"sampled-zero", FrontierFallbackReason.NONE);
		adjusted = tail.adjustLeaf(sampledZero, PROBE);
		assertEquals(1.0d, adjusted.pointRows());
		assertEquals(FrontierLeafEstimate.Guarantee.ESTIMATE, adjusted.guarantee());
	}

	@Test
	void exactTailAdjustmentsHonorPlaneAndNamedContextRestrictions() {
		FrontierMutationTail tail = oneMatchingInsert();
		FrontierLeafEstimate exact = new FrontierLeafEstimate(3.0d, 3.0d, 3.0d, 1.0d,
				"exact-base", FrontierFallbackReason.NONE, FrontierLeafEstimate.Guarantee.EXACT);
		for (int plane : new int[] { FrontierLeafProbe.EXPLICIT, FrontierLeafProbe.INFERRED,
				FrontierLeafProbe.BOTH_PLANES }) {
			for (boolean namedOnly : new boolean[] { false, true }) {
				FrontierLeafProbe probe = new FrontierLeafProbe(plane, FrontierLeafProbe.PREDICATE,
						0L, 2L, 0L, 0L, 0, namedOnly);
				FrontierLeafEstimate adjusted = tail.adjustLeaf(exact, probe);
				double expected = plane != FrontierLeafProbe.INFERRED && !namedOnly ? 4.0d : 3.0d;
				assertEquals(expected, adjusted.pointRows(), "plane=" + plane + ", named=" + namedOnly);
				assertEquals(FrontierLeafEstimate.Guarantee.EXACT, adjusted.guarantee());
			}
		}
	}

	@Test
	void unavailableBaseCannotBePromotedByACompleteMutationTail() {
		for (FrontierFallbackReason reason : FrontierFallbackReason.values()) {
			if (reason == FrontierFallbackReason.NONE) {
				continue;
			}
			FrontierLeafEstimate unavailable = FrontierLeafEstimate.unavailable(reason);
			for (FrontierMutationTail tail : List.of(FrontierMutationTail.EMPTY, oneMatchingInsert())) {
				FrontierLeafEstimate adjusted = tail.adjustLeaf(unavailable, PROBE);
				assertEquals(unavailable, adjusted, "the original unavailable evidence must survive " + reason);
				assertEquals(FrontierLeafEstimate.Guarantee.UNAVAILABLE, adjusted.guarantee());
			}
		}
	}

	private static FrontierMutationTail oneMatchingInsert() {
		return new FrontierMutationTail(List.of(new FrontierMutation(1L, 1L, true, true, 1L, 2L, 3L, 0L)), 1);
	}
}
